using System;using System.IO;using System.Text;using System.Diagnostics;using System.Threading;using System.Collections.Generic;using Newtonsoft.Json.Linq;using SpatialWallpaper.Supervision;using SpatialWallpaper.Supervision.Windows;using SpatialWallpaper.Supervision.Broker;using SpatialWallpaper.Sdk.Hosting;
static class StorageMatrixChecks {
 static string output,authors,attempts;static Stopwatch clock=Stopwatch.StartNew();static PrivateStation station;static FaultJournal journal;static WorkerImage image;static ValidatorLauncher validator;static StorageBroker storage;static JArray results=new JArray();
 static void Need(bool value,string code){if(!value)throw new Exception(code);}
 static WorkerImage Image(string root,string executable,string inventory,string field){var files=new Dictionary<string,string>();foreach(var item in ((JObject)JObject.Parse(File.ReadAllText(inventory))[field]).Properties())files.Add(item.Name,(string)item.Value);return new WorkerImage(root,executable,files);}
 sealed class Run:IDisposable {public WindowsManagedWorker Worker;public AttemptReceipt Receipt;public string Label;public void Dispose(){try{File.WriteAllBytes(Path.Combine(output,Label+".log"),Worker.ReadLog());}finally{try{journal.MarkStopping(Receipt);}finally{try{Worker.Kill();}finally{Worker.Dispose();journal.Complete(Receipt);}}}}}
 static Run Start(Guid install,int role,string label,bool preview=false){string directory=Path.Combine(authors,role.ToString());string build=(string)JObject.Parse(File.ReadAllText(Path.Combine(directory,"author.json")))["build"];var receipt=journal.Begin(install,build,Guid.NewGuid(),1,StartIntent.Manual);var launcher=new WindowsWorkerLauncher(station,image,attempts,()=>clock.ElapsedMilliseconds,640,360,admission:validator,persistence:storage);var request=new LaunchRequest(install,build,receipt.Instance,1,StartIntent.Manual,Path.Combine(directory,"scene.spatial"),RuntimeLimits.ProcessBytes,preview);return new Run{Worker=(WindowsManagedWorker)launcher.Start(request,receipt,pid=>journal.RecordProcess(receipt,pid)),Receipt=receipt,Label=label};}
 static StorageResult Read(Run run,string key){return storage.Read(run.Worker.Session,key).GetAwaiter().GetResult();}
 static string Text(StorageResult result){return result.Value==null?null:Encoding.UTF8.GetString(result.Value);}
 static StorageResult Wait(Run run,string key){var time=Stopwatch.StartNew();while(time.ElapsedMilliseconds<25000){var sample=run.Worker.Sample();Need(sample.Alive&&!sample.ProtocolFault,"worker-failed-"+run.Label+"-"+run.Worker.ReadDiagnostic());var error=Read(run,"author-error");Need(error.Failure!=StorageFailure.None||error.Value==null,"author-error-"+Text(error));var result=Read(run,key);if(result.Failure==StorageFailure.None&&result.Value!=null&&run.Worker.Sequence>0)return result;Thread.Sleep(20);}throw new Exception("author-result-timeout-"+run.Label+"-"+key);}
 static void Open(){storage=new StorageBroker(Path.Combine(output,"storage"));storage.Initialized.GetAwaiter().GetResult();}
 static void Close(){storage.Close();storage.Completion.GetAwaiter().GetResult();}
 static void Observe(Guid install,string label,string expected,long expectedReadVersion,bool preview=false){using(var run=Start(install,3,label,preview)){var revision=Wait(run,"read-version");var observed=Read(run,"observed");Need(observed.Failure==StorageFailure.None&&Text(revision)==expectedReadVersion.ToString()&&Text(observed)==expected,"reader-mismatch-"+label);results.Add(new JObject{{"case",label},{"pid",run.Worker.ProcessId},{"frames",run.Worker.Sequence},{"read_version",Text(revision)},{"observed",Text(observed)},{"installation",install.ToString()},{"preview",preview}});}}
 static void ReadErrorNegative(){Guid installation=Guid.NewGuid();string directory=Path.Combine(output,"storage","live-"+installation.ToString("N"));Directory.CreateDirectory(directory);string path=Path.Combine(directory,"state.bin");File.WriteAllBytes(path,new byte[]{0});int injected=0;
  StorageBroker.BeforeReadReply=(session,key,result)=>{if(session.Installation==installation&&key=="winner"&&result.Failure==StorageFailure.Io&&Interlocked.CompareExchange(ref injected,1,0)==0)File.Delete(path);};
  try{using(var run=Start(installation,3,"read-io-negative")){bool rejected=false;try{Wait(run,"read-version");}catch(Exception error){Need(error.Message=="author-error-Io","wrong-negative-failure-"+error.Message);rejected=true;}Need(injected==1&&rejected&&Read(run,"read-version").Value==null,"read-Io-falsely-accepted-as-empty");results.Add(new JObject{{"case","read-Io-rejected-after-storage-recovered"},{"author_error",Text(Read(run,"author-error"))},{"read_version_marker_absent",true},{"pid",run.Worker.ProcessId}});}}finally{StorageBroker.BeforeReadReply=null;}}
 static void LogFailureCleanup(){var run=Start(Guid.NewGuid(),3,"log-failure-cleanup");try{Wait(run,"read-version");Directory.CreateDirectory(Path.Combine(output,run.Label+".log"));}catch{run.Dispose();throw;}bool rejected=false;try{run.Dispose();}catch(UnauthorizedAccessException){rejected=true;}catch(IOException){rejected=true;}Need(rejected&&station.ChildCount==0&&!run.Worker.Session.Allows("private-storage"),"log-failure-skipped-worker-cleanup");results.Add(new JObject{{"case","log-write-failure-still-cleans-worker"},{"child_count",station.ChildCount},{"session_closed",true}});}
 static void MarkerConflict(){Guid installation=Guid.NewGuid();Action first=null;int reads=0,winnerWrites=0,markerConflicts=0;
  StorageBroker.PublishReadReply=(session,key,result,publish)=>{if(session.Installation!=installation||key!="winner"||reads>=2){publish();return;}Need(result.Failure==StorageFailure.None&&result.Version==1,"marker-race-read-version");reads++;if(reads==1)first=publish;else{first();publish();}};
  StorageBroker.BeforeWriteReply=(session,changes,result)=>{if(session.Installation!=installation)return;if(changes.ContainsKey("winner"))winnerWrites++;else if((changes.ContainsKey("resultA")||changes.ContainsKey("resultB"))&&result.Failure==StorageFailure.Conflict)markerConflicts++;};
  try{using(var a=Start(installation,1,"marker-race-a")){var time=Stopwatch.StartNew();while(Volatile.Read(ref reads)<1){Need(time.ElapsedMilliseconds<15000&&a.Worker.Sample().Alive,"marker-first-read-timeout");Thread.Sleep(20);}using(var b=Start(installation,2,"marker-race-b")){string ra=Text(Wait(a,"resultA")),rb=Text(Wait(b,"resultB"));Need(ra=="success"&&rb=="Conflict"&&Text(Read(a,"winner"))=="A"&&Read(a,"winner").Version==3,"marker-retry-changed-winner");Need(reads==2&&winnerWrites==2&&markerConflicts==1,"marker-race-not-exercised");results.Add(new JObject{{"case","result-marker-conflict-retries-without-retrying-winner"},{"deferred_same_version_reads",reads},{"winner_write_attempts",winnerWrites},{"marker_conflicts",markerConflicts},{"result_a",ra},{"result_b",rb}});}}}finally{StorageBroker.PublishReadReply=null;StorageBroker.BeforeWriteReply=null;first?.Invoke();}}
 static int Main(string[] args){try{
  output=args[0];authors=args[2];attempts=args[4];Guid installation=Guid.NewGuid(),other=Guid.NewGuid(),preserved=Guid.NewGuid();BrokerSession closedA,closedB;string winner;
  using(station=new PrivateStation())using(journal=new FaultJournal(Path.Combine(output,"journal"))){
   image=Image(Path.Combine(args[1],"player"),"Worker.exe",Path.Combine(args[1],"report.json"),"runtime_files");validator=new ValidatorLauncher(station,Image(args[3],"Validator.exe",Path.Combine(args[3],"build.json"),"files"),attempts);Open();
   try{
    using(var a=Start(installation,1,"cas-a"))using(var b=Start(installation,2,"cas-b")){
     Need(a.Worker.ProcessId!=b.Worker.ProcessId&&a.Worker.Sample().Alive&&b.Worker.Sample().Alive,"not-two-live-workers");
     string ra=Text(Wait(a,"resultA")),rb=Text(Wait(b,"resultB"));winner=Text(Read(a,"winner"));
     Need((ra=="success"&&rb=="Conflict"&&winner=="A")||(rb=="success"&&ra=="Conflict"&&winner=="B"),"real-workers-CAS-not-one-success-one-conflict");Need(Read(a,"winner").Version==3,"conflict-changed-version-or-extra-write");
     results.Add(new JObject{{"case","two-live-LPAC-workers-CAS"},{"pid_a",a.Worker.ProcessId},{"pid_b",b.Worker.ProcessId},{"result_a",ra},{"result_b",rb},{"winner",winner},{"version",3},{"frames_a",a.Worker.Sequence},{"frames_b",b.Worker.Sequence}});closedA=a.Worker.Session;closedB=b.Worker.Session;
    }
    Need(storage.Commit(closedA,3,new Dictionary<string,byte[]>{{"winner",new byte[]{1}}}).GetAwaiter().GetResult().Failure==StorageFailure.Closed,"stopped-writer-not-revoked");
   }finally{Close();}
   Open();try{Observe(installation,"cross-build-after-broker-restart",winner,3);Observe(other,"other-installation-empty",null,0);Observe(installation,"preview-empty",null,0,true);using(var run=Start(preserved,2,"unrelated-installation-seed")){Need(Text(Wait(run,"resultB"))=="success"&&Text(Read(run,"winner"))=="B","other-installation-seed-failed");}}finally{Close();}
   using(var store=new PrivateStore(Path.Combine(output,"storage"))){store.Uninstall(installation);store.Uninstall(installation);Need(!Directory.Exists(Path.Combine(output,"storage","live-"+installation.ToString("N")))&&!Directory.Exists(Path.Combine(output,"storage","preview-"+installation.ToString("N"))),"uninstall-left-namespace");}
   Open();try{
    Need(storage.Read(closedA,"winner").GetAwaiter().GetResult().Failure==StorageFailure.Closed&&storage.Read(closedB,"winner").GetAwaiter().GetResult().Failure==StorageFailure.Closed,"uninstall-revived-old-session");
    Observe(installation,"same-id-reinstalled-empty",null,0);Observe(installation,"preview-cleared",null,0,true);Observe(Guid.NewGuid(),"new-id-reinstalled-empty",null,0);
    Observe(preserved,"unrelated-installation-nonempty-preserved","B",2);ReadErrorNegative();LogFailureCleanup();MarkerConflict();
   }finally{Close();}
   Need(station.ChildCount==0,"matrix-child-leak");
  }
  File.WriteAllText(Path.Combine(output,"results.json"),results.ToString());Console.WriteLine("PASS real dual LPAC Worker CAS, cross-build persisted read, install isolation, revoked sessions and core uninstall/reinstall; product uninstall UI not covered");return 0;
 }catch(Exception error){Console.Error.WriteLine(error);File.WriteAllText(Path.Combine(output,"partial-results.json"),results.ToString());return 1;}}
}
